// Works for publishers, custom keys, default models, and custom models
type IdentifierType = number | string

export function getNewIdentifiersToAllow<T extends IdentifierType>({
  isAllowlist,
  currentIdentifiersInList,
  selectedIdentifiers,
}: {
  isAllowlist: boolean
  currentIdentifiersInList: Set<T>
  selectedIdentifiers: Set<T>
}) {
  if (isAllowlist) return selectedIdentifiers.difference(currentIdentifiersInList)
  return currentIdentifiersInList.difference(selectedIdentifiers)
}

export function getNewIdentifiersToBlock<T extends IdentifierType>({
  isAllowlist,
  currentIdentifiersInList,
  selectedIdentifiers,
}: {
  isAllowlist: boolean
  currentIdentifiersInList: Set<T>
  selectedIdentifiers: Set<T>
}) {
  if (isAllowlist) return currentIdentifiersInList.difference(selectedIdentifiers)
  return selectedIdentifiers.difference(currentIdentifiersInList)
}
