import type {CustomKey, CustomModel} from '@github-ui/models-byok/types'
import type {DefaultModel} from '../types'

/**
 * Find custom keys whose models are all allowed.
 */
export function getAllowedCustomKeyIds({
  allowedCustomModelIds,
  customKeyIds,
  modelIdsByCustomKeyId,
}: {
  allowedCustomModelIds: Set<number>
  customKeyIds: number[]
  modelIdsByCustomKeyId: Map<number, Set<number>>
}) {
  return new Set(
    customKeyIds.filter(customKeyId =>
      (modelIdsByCustomKeyId.get(customKeyId) ?? new Set()).isSubsetOf(allowedCustomModelIds),
    ),
  )
}

/**
 * Find custom keys that have no allowed models.
 */
export function getBlockedCustomKeyIds({
  allowedCustomModelIds,
  customKeyIds,
  modelIdsByCustomKeyId,
}: {
  allowedCustomModelIds: Set<number>
  customKeyIds: number[]
  modelIdsByCustomKeyId: Map<number, Set<number>>
}) {
  return new Set(
    customKeyIds.filter(customKeyId =>
      allowedCustomModelIds.isDisjointFrom(modelIdsByCustomKeyId.get(customKeyId) ?? new Set()),
    ),
  )
}

export function getModelIdsByCustomKeyId({customKeys, models}: {customKeys: CustomKey[]; models: CustomModel[]}) {
  return new Map(
    customKeys.map(customKey => [
      customKey.id,
      new Set(models.filter(model => model.customKeyId === customKey.id).map(model => model.id)),
    ]),
  )
}

export function getCustomKeysByModelId({
  customKeys,
  models,
}: {
  customKeys: CustomKey[]
  models: Array<CustomModel | DefaultModel>
}) {
  const customKeysById = new Map(customKeys.map(customKey => [customKey.id, customKey]))
  const result = new Map<number, CustomKey>()
  for (const model of models) {
    if ('customKeyId' in model) {
      const customKey = customKeysById.get(model.customKeyId)
      if (customKey) result.set(model.id, customKey)
    }
  }
  return result
}
