import {useMemo, useState} from 'react'
import {UnderlineNav} from '@primer/react'
import type {CustomKey, CustomModel} from '@github-ui/models-byok/types'
import type {DefaultModel, Publisher} from '../types'
import {ModelRulesList} from './ModelRulesList'
import {AddRuleDialog} from './AddRuleDialog'
import {SelectionProvider} from '../contexts/SelectionContext'
import {RuleListTypeToggle} from './RuleListTypeToggle'
import {PublisherRulesList} from './PublisherRulesList'
import {useOrganizationAccessPolicy} from '../contexts/OrganizationAccessPolicyContext'
import {usePublishers} from '../contexts/PublishersContext'
import {getAllowedCustomKeyIds, getBlockedCustomKeyIds, getModelIdsByCustomKeyId} from '../utils/custom-keys'

export function RulesTable({
  customKeys,
  models,
  orgDisplayLogin,
  publishers,
}: {
  customKeys: CustomKey[]
  models: Array<CustomModel | DefaultModel>
  orgDisplayLogin: string
  publishers: Publisher[]
}) {
  const customModels = useMemo(() => models.filter(model => 'customKeyId' in model), [models])
  const customKeyIds = customKeys.map(customKey => customKey.id)

  const modelIdsByCustomKeyId = useMemo(
    () => getModelIdsByCustomKeyId({customKeys, models: customModels}),
    [customModels, customKeys],
  )
  const {allowedPublisherIds, blockedPublisherIds} = usePublishers()
  const {allowedCustomModelIds, allowedModelKeys, isAllowlist, isModelsEnabled} = useOrganizationAccessPolicy()
  const allowedCustomKeyIds = getAllowedCustomKeyIds({allowedCustomModelIds, customKeyIds, modelIdsByCustomKeyId})
  const blockedCustomKeyIds = getBlockedCustomKeyIds({allowedCustomModelIds, customKeyIds, modelIdsByCustomKeyId})
  const totalAffectedCustomKeys = isAllowlist ? allowedCustomKeyIds.size : blockedCustomKeyIds.size
  const totalAffectedPublishers = isAllowlist ? allowedPublisherIds.size : blockedPublisherIds.size
  const totalAffectedPublishersAndCustomKeys = totalAffectedPublishers + totalAffectedCustomKeys
  const totalAffectedModels = isAllowlist
    ? allowedCustomModelIds.size + allowedModelKeys.size
    : Math.max(models.length - allowedModelKeys.size - allowedCustomModelIds.size, 0)
  const [isPublishersTabActive, setIsPublishersTabActive] = useState(
    totalAffectedPublishersAndCustomKeys > 0 || totalAffectedModels < 1,
  )
  const listNamePrefix = isAllowlist ? 'Allowed' : 'Blocked'

  if (!isModelsEnabled) return null

  return (
    <>
      <div className="tmp-mb-3 d-md-flex flex-row flex-justify-between flex-items-center">
        <RuleListTypeToggle />
        <SelectionProvider customKeys={customKeys} models={models} publishers={publishers}>
          <AddRuleDialog customKeys={customKeys} models={models} publishers={publishers} />
        </SelectionProvider>
      </div>
      <div className="Box Box--condensed">
        <UnderlineNav aria-label="View selected publishers or models">
          <UnderlineNav.Item
            as="button"
            aria-current={isPublishersTabActive ? 'location' : undefined}
            onSelect={() => setIsPublishersTabActive(true)}
            counter={totalAffectedPublishersAndCustomKeys}
          >
            {listNamePrefix} publishers
          </UnderlineNav.Item>
          <UnderlineNav.Item
            as="button"
            aria-current={!isPublishersTabActive ? 'location' : undefined}
            onSelect={() => setIsPublishersTabActive(false)}
            counter={totalAffectedModels}
          >
            {listNamePrefix} models
          </UnderlineNav.Item>
        </UnderlineNav>
        {isPublishersTabActive ? (
          <PublisherRulesList
            allowedCustomKeyIds={allowedCustomKeyIds}
            blockedCustomKeyIds={blockedCustomKeyIds}
            modelIdsByCustomKeyId={modelIdsByCustomKeyId}
            orgDisplayLogin={orgDisplayLogin}
            customKeys={customKeys}
            publishers={publishers}
          />
        ) : (
          <ModelRulesList orgDisplayLogin={orgDisplayLogin} customKeys={customKeys} models={models} />
        )}
      </div>
    </>
  )
}
